    }finally{stop.Cancel();server.Stop();await fakeEngine;await Task.WhenAll(sessions);await new NpgsqlCommand($"set search_path to public; drop schema {schema} cascade",db).ExecuteNonQueryAsync();}
    Console.WriteLine($"PASS: {checks} Web Push crypto, endpoint, OAuth compatibility and durable queue checks");return 0;
}finally{Directory.Delete(path,true);}

